package br.com.serviceflow.api.service;
import br.com.serviceflow.api.dto.auth.*; import br.com.serviceflow.api.model.Usuario; import br.com.serviceflow.api.repository.UsuarioRepository; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.LocalDateTime; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class SupportRecoveryService {
 private final UsuarioRepository users; private final JavaMailSender mail; private final PasswordEncoder encoder; private final CredentialTokenService tokens; private final String supportEmail,supportKey,from;
 public SupportRecoveryService(UsuarioRepository users,JavaMailSender mail,PasswordEncoder encoder,CredentialTokenService tokens,@Value("${app.support.email:}") String supportEmail,@Value("${app.support.key:}") String supportKey,@Value("${spring.mail.username:}") String from){this.users=users;this.mail=mail;this.encoder=encoder;this.tokens=tokens;this.supportEmail=supportEmail;this.supportKey=supportKey;this.from=from;}
 public MessageResponse request(ForgotPasswordRequest x){users.findByEmailIgnoreCase(x.email()).ifPresent(u->{if(supportEmail.isBlank())throw new IllegalStateException("SUPPORT_EMAIL não configurado");SimpleMailMessage m=new SimpleMailMessage();m.setFrom(from);m.setTo(supportEmail);m.setSubject("ServiceFlow - solicitação de nova senha");m.setText("Usuário: "+u.getNome()+"\nE-mail: "+u.getEmail()+"\nData: "+LocalDateTime.now()+"\n\nConfirme a identidade antes de redefinir o acesso.");mail.send(m);});return new MessageResponse("Se o e-mail estiver cadastrado, a solicitação será encaminhada ao suporte",null);}
 @Transactional public void reset(String key,SupportResetRequest x){if(supportKey.isBlank()||!MessageDigest.isEqual(supportKey.getBytes(StandardCharsets.UTF_8),key.getBytes(StandardCharsets.UTF_8)))throw new BadCredentialsException("Chave de suporte inválida");Usuario u=users.findByEmailIgnoreCase(x.email()).orElseThrow(()->new BadCredentialsException("Usuário não encontrado"));u.setSenhaHash(encoder.encode(x.temporaryPassword()));u.setTrocaSenhaObrigatoria(true);tokens.revokeAllSessions(u.getId());}
}
